import * as O from './old/src/cart.js';
import * as N from './new/src/cart.js';
import * as W from '/app/src/cart.js';
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const rates = [['omitted'], ['0', 0], ['-0', -0], ['undefined', undefined], ['null', null], ['"0"', '0'], ['false', false], ['0.0', 0.0]];
let n = 0, diffs = [];
const check = (items, label) => {
  for (const [name, ...arg] of rates) {
    const o = O.total(items, ...arg), w = W.total(items, ...arg), nn = N.total(items, ...arg);
    n++;
    if (!Object.is(o, w) || !Object.is(o, nn)) diffs.push({ label, rate: name, old: o, new: w, items: JSON.stringify(items).slice(0, 200) });
  }
};
// hand-picked edge cases
const L = (c, p, q = 1) => Array.from({ length: c }, () => ({ price: p, qty: q }));
const edge = {
  empty: [], one: L(1, 1000), nine: L(9, 1000), ten: L(10, 1000), eleven: L(11, 1000), ten33: L(10, 33), ten1: L(10, 1),
  tenHalf: L(10, 0.5), tenFloat: L(10, 19.99, 3), neg: L(10, -33), negSmall: L(3, -5), zeroQty: L(12, 100, 0),
  missingQty: [{ price: 100 }], strPrice: [{ price: '100', qty: 2 }], big: L(10, 9007199254740, 1), huge: L(20, 1e300, 1e10),
  nanp: [{ price: NaN, qty: 1 }], inf: L(10, Infinity), tiny: L(10, 1e-320), half: [{ price: 0.5, qty: 1 }], negHalf: [{ price: -0.5, qty: 1 }],
  ten05: L(10, 0.1), mix: [...L(9, 7), { price: 3, qty: 0 }],
};
for (const [k, v] of Object.entries(edge)) check(v, k);
// exhaustive small integers: 10..12 lines of same price, subtotal covers every .5 boundary
for (let c = 0; c <= 25; c++) for (let p = 0; p <= 2000; p++) check(L(c, p), `grid c=${c} p=${p}`);
// random
for (let i = 0; i < 200000; i++) {
  const c = Math.floor(rnd() * 30);
  const frac = rnd() < 0.3;
  const items = Array.from({ length: c }, () => ({ price: frac ? Math.round(rnd() * 1e6) / 100 : Math.floor(rnd() * 100000), qty: Math.floor(rnd() * 20) }));
  check(items, 'random');
}
console.log('rate-0 comparisons run:', n, 'differences:', diffs.length);
console.log(diffs.slice(0, 10));
