console.log('sanity old/new @0.1 single 1000:', O.total(L(1, 1000), 0.1), W.total(L(1, 1000), 0.1));
console.log('sanity old/new @0.1 ten x1000:', O.total(L(10, 1000), 0.1), W.total(L(10, 1000), 0.1));
EOF
