import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// Issue #12: the customer's discount is applied exactly once.
test('total applies the customer discount once', () => {
  // 1000 * (1 - 0.1) = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// `count` cart lines of one item each at `price`.
const lines = (count, price) => Array.from({ length: count }, () => ({ price, qty: 1 }));

test('total applies the bulk discount once, after the customer discount, at 10 lines', () => {
  // 10000 * (1 - 0.1) = 9000, then 9000 * (1 - 0.05) = 8550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('total applies no bulk discount below 10 lines', () => {
  // 9000 * (1 - 0.1) = 8100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('total with a zero discount rate keeps the bulk discount at 10 lines', () => {
  // 10000 * (1 - 0.05) = 9500
  assert.equal(total(lines(10, 1000), 0), 9500);
});

test('total with a zero discount rate still rounds to the nearest unit', () => {
  // 330 * (1 - 0.05) = 313.5, rounded to 314 (behaviour before issue #12, kept as is)
  assert.equal(total(lines(10, 33), 0), 314);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
